style.css:
@-moz-document domain("fitt-iitd.in") {
input.form-control[type="text"] {
    /* Force the input to be taller */
    height: 100px !important;
    
    /* If you want the box to allow scrolling once the text is larger
       than 100px, you can optionally add: */
    overflow: auto !important;
    
    /* If you would like the input to “wrap” text visually (though still
       a single-line control by default), you can add:
       white-space: normal !important;
       word-wrap: break-word !important;
       However, note that <input type="text"> is not truly multi-line. */
  }
}
